// Widget 构造函数中
webServer_ = new WebServer(8080);
webServer_->set_command_handler([this](auto& method, auto& path, auto& body) {
    std::string result;
    QMetaObject::invokeMethod(this, [&]() {
        result = handle_web_command(method, path, body);
    }, Qt::BlockingQueuedConnection);
    return result;
});
webServer_->start();

// 定时推送状态 (1Hz)
webServer_->push_status(get_status_json_());

// 析构函数中优先停止
webServer_->stop();
delete webServer_;

// 按钮点击 -> REST API
async function toggleStream(camNum) {
  if (cam[camNum].streaming) {
    await apiPost(`/cam/${camNum}/stream/stop`);
    stopMjpegVideo(camNum);
  } else {
    await apiPost(`/cam/${camNum}/stream/start`);
    setTimeout(() => startMjpegVideo(camNum), 1000);
  }
}
